import { runAgent } from "../lib/llm.js";
import { obj, str, arr } from "./schema.js";
import { writerSchema } from "./briefingWriter.js";

export const DISCLAIMER =
  "For internal advisor use only. This summary is generated by AI from public market data and SEC filings, may contain errors, and is not investment advice or a recommendation to buy, sell or hold any security. Verify against the original filings before use with clients.";

const schema = obj({
  revised: writerSchema,
  issues_found: arr(
    obj({
      original: str("The problematic phrase"),
      reason: str("Why it is a compliance problem"),
      fix: str("How it was rewritten"),
    }),
    "Every problem found and fixed; empty if none"
  ),
});

export function complianceReviewer({ draft, briefingId }) {
  return runAgent({
    agent: "compliance_reviewer",
    briefingId,
    effort: "low",
    schema,
    system: `You are the Compliance Reviewer at a wealth management firm. You review AI-written stock briefings before advisors see them.
Rewrite any text that:
- recommends buying, selling or holding, or says a stock is a good/bad investment
- predicts or targets future prices or returns
- makes promises or guarantees ("will", "certain", "risk-free") about performance
- reads as personalized advice ("you should", "clients should")
- uses promotional or exaggerated language
Keep everything else unchanged, including all facts and figures. Return the full revised briefing.`,
    prompt: `Draft briefing (JSON):\n${JSON.stringify(draft, null, 2)}`,
  });
}
